values
  ('hero','hero-name','Gaetano Russo','Gaetano Russo','','', '{"selector":"#hero-title"}'::jsonb,0,'published'),
  ('hero','hero-intro','Introduzione hero','Hero introduction','Gestisco sistemi, utenti e connettività in contesti aziendali con un approccio metodico alla diagnosi; applico lo stesso metodo anche ai progetti web.','I manage systems, users and connectivity in corporate environments with a methodical approach to diagnostics, and apply the same method to web projects.','{"selector":".hero-intro"}'::jsonb,1,'published'),
  ('profile','profile-positioning','Posizionamento profilo','Profile positioning','L’infrastruttura IT è il mio lavoro principale. Il web è il percorso che sto costruendo accanto.','IT infrastructure is my main role. Web development is the path I am building alongside it.','{"selector":".profile-story__heading h2"}'::jsonb,0,'published'),
  ('contact_copy','contact-introduction','Introduzione contatti','Contact introduction','Se vuoi conoscere meglio la mia esperienza, approfondire un progetto o valutare un’opportunità professionale, puoi contattarmi qui.','If you would like to learn more about my experience, discuss a project or explore a professional opportunity, you can contact me here.','{"selector":".contact-copy > p:last-of-type"}'::jsonb,0,'published'),
  ('seo','homepage-description','Meta description homepage','Homepage meta description','Portfolio di Gaetano Russo, IT Infrastructure Specialist: sistemi Windows, Active Directory, networking, SAP e progetti web tecnici.','Gaetano Russo portfolio: IT infrastructure, Windows systems, Active Directory, networking, SAP and technical web projects.','{"selector":"meta[name=description]"}'::jsonb,0,'published')
