insert into public.content_items (content_type, slug, title_it, title_en, data, sort_order, status) values
  ('infrastructure_case','identita-accessi','Gestione di utenti e permessi in dominio Windows','Managing users and permissions in a Windows domain',$json${"eyebrow":{"it":"Caso principale · Identità e accessi","en":"Main case · Identity and access"},"scenario":{"it":"Supporto quotidiano a utenti e risorse condivise in un ambiente aziendale basato su Windows Server e Active Directory.","en":"Day-to-day support for users and shared resources in a corporate Windows Server and Active Directory environment."},"problem":{"it":"Un accesso negato o una policy non applicata può dipendere dall’account, dai gruppi, dall’OU, dalla GPO o dai servizi di risoluzione del dominio.","en":"Denied access or a policy that does not apply may depend on the account, groups, OU, GPO or domain name-resolution services."},"analysis":{"it":"Verifico identità, appartenenze, ambito della policy, DNS e autenticazione prima di modificare la configurazione.","en":"I check identity, memberships, policy scope, DNS and authentication before changing configuration."},"intervention":{"it":"Gestisco utenti, gruppi, OU, permessi e GPO e intervengo sui servizi collegati quando necessario.","en":"I manage users, groups, OUs, permissions and GPOs and address related services when needed."},"verification":{"it":"Verifico nuovamente accesso, applicazione della policy e disponibilità della risorsa.","en":"I recheck access, policy application and resource availability."},"technologies":["Windows Server","Active Directory","GPO","DNS","DHCP"],"result":{"it":"L’utente torna a lavorare con i soli permessi necessari.","en":"The user can work again with only the required permissions."},"competencies":[{"it":"Gestione delle identità","en":"Identity management"},{"it":"Troubleshooting controllato","en":"Controlled troubleshooting"}],"diagram":[{"it":"Utente","en":"User"},"Active Directory",{"it":"Permessi","en":"Permissions"},{"it":"Risorsa autorizzata","en":"Authorised resource"}]}$json$::jsonb,10,'published'),
  ('infrastructure_case','connettivita','Diagnosi di connettività tra client e servizio aziendale','Diagnosing connectivity between a client and a business service',$json${"eyebrow":{"it":"Networking e accesso remoto","en":"Networking and remote access"},"scenario":{"it":"Supporto a reti aziendali, reparti produttivi e collegamenti VPN.","en":"Support for corporate networks, production departments and VPN connections."},"problem":{"it":"Un client non raggiunge una risorsa oppure la connessione remota non consente di proseguire il lavoro.","en":"A client cannot reach a resource, or a remote connection prevents work from continuing."},"analysis":{"it":"Verifico configurazione IP, percorso di rete, segmentazione, VPN e raggiungibilità del servizio.","en":"I check IP configuration, network path, segmentation, VPN and service reachability."},"intervention":{"it":"Correggo la configurazione coinvolta o circoscrivo il punto di guasto.","en":"I correct the affected configuration or isolate the fault domain."},"verification":{"it":"Ripeto i test di raggiungibilità e controllo l’accesso al servizio.","en":"I repeat reachability tests and confirm service access."},"technologies":["LAN","VLAN","VPN","Routing","Switching"],"result":{"it":"La causa viene isolata e l’accesso ripristinato o affidato al livello competente con contesto utile.","en":"The cause is isolated and access is restored or handed over with useful context."},"competencies":[{"it":"Troubleshooting per livelli","en":"Layered troubleshooting"}]}$json$::jsonb,20,'published'),
  ('infrastructure_case','supporto-sap','Supporto tecnico su accessi e componenti SAP','Technical support for SAP access and components',$json${"eyebrow":{"it":"Supporto applicativo","en":"Application support"},"scenario":{"it":"Assistenza agli utenti SAP in ambienti ERP.","en":"Support for SAP users in ERP environments."},"problem":{"it":"L’utente incontra un problema di accesso, configurazione del client o utilizzo dell’applicazione.","en":"A user encounters an access, client configuration or application issue."},"analysis":{"it":"Distinguo il problema locale da quello applicativo e verifico utente, client e collegamento.","en":"I distinguish local from application issues and check user, client and connection."},"intervention":{"it":"Intervengo su SAP GUI, gestione utenti, SAP Router e troubleshooting.","en":"I work on SAP GUI, user management, SAP Router and troubleshooting."},"verification":{"it":"Confermo con l’utente il nuovo accesso o preparo un’escalation circostanziata.","en":"I confirm access with the user or prepare a well-scoped escalation."},"technologies":["SAP GUI","SAP Router","ABAP"],"result":{"it":"Il problema viene risolto nel perimetro del supporto oppure inoltrato conservando il contesto.","en":"The issue is resolved within support scope or escalated with its context."},"competencies":[{"it":"Supporto agli utenti","en":"User support"}]}$json$::jsonb,30,'published'),
  ('infrastructure_case','operations','Manutenzione dell’infrastruttura in ambiente produttivo','Infrastructure maintenance in a production environment',$json${"eyebrow":"Operations","scenario":{"it":"Gestione operativa di server, ambienti virtualizzati, utenti e servizi collegati alla produzione.","en":"Operational management of servers, virtual environments, users and production-related services."},"problem":{"it":"Aggiornamenti, backup e anomalie devono essere gestiti senza introdurre modifiche non controllate.","en":"Updates, backups and incidents must be handled without uncontrolled changes."},"analysis":{"it":"Valuto servizio, dipendenze e rischio operativo.","en":"I assess the service, dependencies and operational risk."},"intervention":{"it":"Eseguo attività su Windows Server, VMware, backup e aggiornamenti con una sequenza verificabile.","en":"I work on Windows Server, VMware, backups and updates using a verifiable sequence."},"verification":{"it":"Controllo disponibilità del servizio ed esito dell’attività.","en":"I check service availability and the activity outcome."},"technologies":["VMware","Windows Server","Backup","VPN"],"result":{"it":"Il servizio viene riconsegnato dopo una verifica tecnica.","en":"The service is handed back after technical verification."},"competencies":[{"it":"Continuità operativa","en":"Operational continuity"}]}$json$::jsonb,40,'published')
insert into public.content_items (content_type, slug, title_it, title_en, data, sort_order, status) values
  ('web_project','portfolio-gaetano-russo','Portfolio professionale di Gaetano Russo','Gaetano Russo’s professional portfolio',$json${"type":{"it":"Progetto personale","en":"Personal project"},"status":"Online","audience":{"it":"Recruiter IT e professionisti interessati a un sito web.","en":"IT recruiters and professionals interested in a website."},"need":{"it":"Presentare nello stesso sito il profilo infrastrutturale e i lavori web senza confondere i due interlocutori.","en":"Present infrastructure experience and web work on the same site without confusing the two audiences."},"decisions":{"it":"Architettura statica, dati separati dall’interfaccia e due percorsi consultabili senza ricaricare la pagina.","en":"Static architecture, data separated from the interface and two paths without page reloads."},"features":{"it":"Contenuti bilingue, tema chiaro/scuro, video adattivo, cookie, modali accessibili, CV con informativa e form EmailJS.","en":"Bilingual content, light/dark theme, adaptive video, cookies, accessible dialogs, privacy-gated CV and EmailJS form."},"problems":{"it":"Organizzare i contenuti esistenti, preservare i deep link e limitare il peso dei video Canva.","en":"Organising existing content, preserving deep links and limiting Canva video impact."},"stack":["HTML5","CSS3","JavaScript","EmailJS","GitHub Pages"],"result":{"it":"Il sito pubblicato comprende homepage, pagine legali, articoli e contenuti bilingue.","en":"The published website includes the homepage, legal pages, articles and bilingual content."},"proof":{"it":"La pagina che stai consultando è il progetto in esecuzione.","en":"The page you are viewing is the running project."},"links":[{"label":{"it":"Apri il sito","en":"Open website"},"href":"https://gaetanorussoits1994-coder.github.io/portfolio-gaetano-russo/"}]}$json$::jsonb,10,'published'),
  ('web_project','luca-magarotto-photography','Luca Magarotto Photography','Luca Magarotto Photography',$json${"type":{"it":"Progetto reale per studio fotografico","en":"Live project for a photography studio"},"status":{"it":"Online","en":"Live"},"audience":{"it":"Fotografo e visitatori interessati ai suoi lavori.","en":"Photographer and visitors interested in his work."},"need":{"it":"Realizzare una presenza online professionale che organizzasse portfolio, progetti Fine Art, articoli e richieste di contatto.","en":"Create a professional online presence for portfolios, Fine Art projects, journal articles and contact enquiries."},"decisions":{"it":"Ho realizzato un sito bilingue con percorsi fotografici distinti e un’area amministrativa riservata con recupero password.","en":"I built a bilingual website with distinct photography paths and a restricted administration area with password recovery."},"features":{"it":"Portfolio In Studio e On Location, Fine Art Prints, Journal, Contatti, selettore IT/EN e accesso amministrativo.","en":"In Studio and On Location portfolios, Fine Art Prints, Journal, Contact, IT/EN selector and admin access."},"problems":{"it":"Organizzare servizi, progetti e contenuti editoriali mantenendo separata l’area di gestione.","en":"Organising services, projects and editorial content while keeping management separate."},"stack":["Next.js","React","Vercel"],"result":{"it":"Il sito è online su dominio personalizzato e le sezioni pubbliche verificate sono accessibili.","en":"The site is live on a custom domain and its verified public sections are accessible."},"links":[{"label":{"it":"Visita il sito","en":"Visit the website"},"href":"https://lucamagarotto42photography.it/"}]}$json$::jsonb,20,'published')
